"925 :   private void addExpr(Node n, int minPrecedence, Context context) {
926 :     if ((NodeUtil.precedence(n.getType()) < minPrecedence) ||
927 :         ((context == Context.IN_FOR_INIT_CLAUSE) && n.isIn())){
928 :       add("(");
929 :       add(n, Context.OTHER);
930 :       add(")");
931 :     } else {
932 :       add(n, context);
933 :     }
934 :   }"

