"1262 :   private  Context getContextForNoInOperator(Context context) {
1263 :     return (context == Context.IN_FOR_INIT_CLAUSE
1264 :         ? Context.IN_FOR_INIT_CLAUSE : Context.OTHER);
1265 :   }"
